// routes/search.js
const express = require('express');
const Movie = require('../models/Movie');
const router = express.Router();

const escapeRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const ci = (s) => ({ $regex: escapeRegex(String(s).trim()), $options: 'i' });

// GET /api/search?q=batman&filter=title|celebs|all
router.get('/', async (req, res) => {
  const { q = '', filter = 'title' } = req.query;
  if (!q.trim()) return res.json([]);
  let query;
  if (filter === 'celebs') query = { celebs: ci(q) };
  else if (filter === 'all') query = { $or: [{ title: ci(q) }, { celebs: ci(q) }] };
  else query = { title: ci(q) };
  res.json(await Movie.find(query));
});

// GET /api/search/advanced?yearFrom=&yearTo=&ratingFrom=&ratingTo=&genre=A,B&director=&writer=
router.get('/advanced', async (req, res) => {
  const { yearFrom, yearTo, ratingFrom, ratingTo, genre, director, writer } = req.query;
  const and = [];
  const range = (from, to, parse) => {
    const r = {};
    if (from !== undefined && from !== '') r.$gte = parse(from);
    if (to !== undefined && to !== '') r.$lte = parse(to);
    return Object.keys(r).length ? r : null;
  };
  const year = range(yearFrom, yearTo, Number);
  if (year) and.push({ year });
  const rating = range(ratingFrom, ratingTo, parseFloat);
  if (rating) and.push({ rating });
  if (genre) {
    const list = (Array.isArray(genre) ? genre : String(genre).split(','))
      .map((g) => g.trim()).filter(Boolean);
    if (list.length) and.push({ genres: { $all: list } });
  }
  if (director) and.push({ director: ci(director) });
  if (writer) and.push({ writer: ci(writer) });
  res.json(await Movie.find(and.length ? { $and: and } : {}));
});

module.exports = router;
